package mx.taller.client;
import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Query; import org.springframework.data.repository.query.Param; import org.springframework.data.domain.Page; import org.springframework.data.domain.Pageable; import java.util.*;
public interface ClienteRepository extends JpaRepository<Cliente,UUID>{boolean existsByEmailIgnoreCase(String e);boolean existsByTelefono(String t); Page<Cliente> findByActivoTrue(Pageable p);Page<Cliente> findByActivoFalse(Pageable p);Optional<Cliente> findByIdAndActivoFalse(UUID id); Optional<Cliente> findByIdAndActivoTrue(UUID id); @Query("select c from Cliente c where c.activo=true and (:texto='' or lower(c.nombre) like lower(concat('%',:texto,'%')) or lower(c.apellido) like lower(concat('%',:texto,'%')) or lower(c.email) like lower(concat('%',:texto,'%')) or c.telefono like concat('%',:texto,'%'))") Page<Cliente> buscarActivos(@Param("texto") String texto,Pageable p);}
